/* ============================================================
   DOI_STOCK  ←  202608 엑셀 적재
   DB : 도우제조원가시스템 (10.100.40.17,14233)
   행 : 112행
   엑셀: 08월 재고수불부(260910).xlsx / 시트 '창고수불(202608)' R3~ (헤더 R2)
   대상: 품목자산분류 IN ('제품','카세트제품')
   키: 제품 MODEL<-품명(5열) / 카세트제품 MODEL<-품번(6열), MODEL_TYPE<-품번(6열), STOCK<-창고(11열)
   * 하위 컬럼에 라벨이 없어 위치 기반 매핑 (기타입고상세 36~38, 기타출고상세 39~46)
   * 7월 대비 보정: '이동처리'(20/32열)를 MOVING에 합산 (8월 464건 발생)
   * RMA_AMT는 08월 제품 반품 리스트.xlsx / 집계 '26.08 입고' 블록에서 UPDATE (합 95,257,838)
   * API 적재분(107행)은 breakdown 21컬럼이 전량 NULL, 카세트 3행·7073P·7110P 누락
   실행: 검증 통과 시 자동 COMMIT, 실패 시 자동 ROLLBACK
   ============================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

/* RMA_AMT 반영 여부 스위치
   1 = 8월 반품금액 95,257,838 을 RMA_AMT 에 반영 (202601 선례와 동일)
   0 = 반영하지 않음        (202602~202607 6개월과 동일하게 0 유지)
   ※ UP_DOI_STOCK_BOH STEP6 이 model_type LIKE '%R' 의 RMA_AMT 를 읽어
      doi_stco 양산행 OUTETC_AMT 로 기입하므로, 1 로 두면 8월 매출원가가
      그만큼 줄어든다. 6·7월과 기준이 달라지는 회계 정책 판단이 필요하다. */
DECLARE @APPLY_RMA BIT = 1;

DECLARE @before INT = (SELECT COUNT(*) FROM [DOI_STOCK] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL');
DELETE FROM [DOI_STOCK] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL';


/* ---------- 제품 반품 리스트 -> RMA_AMT ----------
   MODEL_TYPE 만으로는 행이 특정되지 않는 경우가 있어(8136R = 완제품창고/현장창고 2행)
   반품 수량과 일치하는 INPUT 행으로 한정한다. 각 UPDATE 는 정확히 1행이어야 한다. */
DECLARE @rmarows INT = 0;
IF @APPLY_RMA = 1
BEGIN
UPDATE [DOI_STOCK] SET RMA_AMT=3565861 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'7073R' AND [INPUT]=71;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=1006207 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'7110R' AND [INPUT]=97;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=54984 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'8085R' AND [INPUT]=10;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=4685636 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'810PR' AND [INPUT]=58;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=5417098 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'8122R' AND [INPUT]=148;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=8189758 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'8136R' AND [INPUT]=1473;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=9100 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'8140R' AND [INPUT]=2;  SET @rmarows=@rmarows+@@ROWCOUNT;
UPDATE [DOI_STOCK] SET RMA_AMT=72329194 WHERE YYYYMM='202608' AND SEL_CODE='ACTUAL' AND SITE='HQ' AND MODEL_TYPE=N'902KR' AND [INPUT]=863;  SET @rmarows=@rmarows+@@ROWCOUNT;
END

/* ---------- 검증 ---------- */
DECLARE @ok BIT = 1, @msg NVARCHAR(2000) = N'';
DECLARE @after INT = (SELECT COUNT(*) FROM [DOI_STOCK] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL');
IF @after <> 112 BEGIN SET @ok=0; SET @msg=@msg+N'행수 112 기대, 실제 '+CAST(@after AS NVARCHAR(20))+N'; '; END
IF ABS(ISNULL((SELECT SUM(BOH) FROM DOI_STOCK WHERE YYYYMM='202608'),0) - 41688) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'BOH합계 불일치(기대 41688, 실제 '+CAST(ISNULL((SELECT SUM(BOH) FROM DOI_STOCK WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(INPUT) FROM DOI_STOCK WHERE YYYYMM='202608'),0) - 363802) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'INPUT합계 불일치(기대 363802, 실제 '+CAST(ISNULL((SELECT SUM(INPUT) FROM DOI_STOCK WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(OUT) FROM DOI_STOCK WHERE YYYYMM='202608'),0) - 355178) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'OUT합계 불일치(기대 355178, 실제 '+CAST(ISNULL((SELECT SUM(OUT) FROM DOI_STOCK WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(EOH) FROM DOI_STOCK WHERE YYYYMM='202608'),0) - 50312) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'EOH합계 불일치(기대 50312, 실제 '+CAST(ISNULL((SELECT SUM(EOH) FROM DOI_STOCK WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT COUNT(*) FROM DOI_STOCK WHERE YYYYMM='202608' AND INPUT_PROD+INPUT_MOVING+INPUT_ETC<>INPUT),0) - 0) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'입고항등식위반행 불일치(기대 0, 실제 '+CAST(ISNULL((SELECT COUNT(*) FROM DOI_STOCK WHERE YYYYMM='202608' AND INPUT_PROD+INPUT_MOVING+INPUT_ETC<>INPUT),0) AS NVARCHAR(40))+N'); '; END
IF @APPLY_RMA = 1 AND ABS(ISNULL((SELECT SUM(RMA_AMT) FROM DOI_STOCK WHERE YYYYMM='202608'),0) - 95257838) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'RMA_AMT합계 불일치(기대 95257838, 실제 '+CAST(ISNULL((SELECT SUM(RMA_AMT) FROM DOI_STOCK WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF @APPLY_RMA = 1 AND ABS(ISNULL((SELECT COUNT(*) FROM DOI_STOCK WHERE YYYYMM='202608' AND RMA_AMT<>0),0) - 8) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'RMA행수 불일치(기대 8, 실제 '+CAST(ISNULL((SELECT COUNT(*) FROM DOI_STOCK WHERE YYYYMM='202608' AND RMA_AMT<>0),0) AS NVARCHAR(40))+N'); '; END
IF @APPLY_RMA = 1 AND ABS(ISNULL((SELECT @rmarows),0) - 8) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'RMA UPDATE 적중행 불일치(기대 8, 실제 '+CAST(ISNULL((SELECT @rmarows),0) AS NVARCHAR(40))+N'); '; END

IF @ok = 1
BEGIN
  COMMIT;
  SELECT N'DOI_STOCK 적재 완료' AS 결과, @before AS 삭제전행수, @after AS 적재행수;
END
ELSE
BEGIN
  ROLLBACK;
  SELECT N'DOI_STOCK 검증 실패 — 원상복구' AS 결과, @msg AS 사유;
END
GO